"""Explicit economic corrections from the supplied audit; retain source snapshot."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'lib/practice/alevel-topics'
B={p.stem:json.loads(p.read_text()) for p in D.glob('*.json') if p.stem!='manifest'}
ledger=[]
def fix(s,i,prompt=None,choices=None,explanation=None):
 q=B[s][i-1];before=json.loads(json.dumps(q))
 if prompt is not None:q['prompt']=prompt
 if choices is not None:
  for o,t in zip(q['options'],choices):o['text']=t
 if explanation is not None:q['explanation']=explanation
 if q!=before:ledger.append({'topic':s,'question':i,'before':before,'after':q})
q=B['7-1'][86]
fix('7-1',87,prompt=q['prompt'].replace('3, 0, -3','3, 1, -3'),explanation='Total utility after successive units is 15, 27, 36, 42, 45, 46 and 43. It has a unique maximum after the sixth unit; the seventh reduces it.')
fix('7-1',71,prompt=B['7-1'][70]['prompt'].replace('Which bundle maximises utility?','Which of the listed bundles gives the highest total utility within the budget?'),choices=['1 unit of X and 4 units of Y','3 units of X and 0 units of Y','2 units of X and 2 units of Y','0 units of X and 5 units of Y'],explanation='The listed bundles cost $12, $12, $12 and $10 and yield total utilities of 76, 60, 80 and 50 respectively. The highest utility among them is 80, from 2X and 2Y.')
fix('7-1',76,prompt='A consumer chooses six units of X as part of a utility-maximising bundle within a fixed budget. The seventh unit has low but positive marginal utility. With tastes and other prices unchanged, the price of X falls from $3 to $2. Why might the consumer buy an additional unit?',choices=['Its marginal utility rises as its purchase price falls.','Its marginal utility per dollar falls relative to other goods.','Its marginal utility per dollar rises relative to other goods.','Its purchase leaves less income available for other goods.'],explanation='With unchanged tastes, the seventh unit retains its positive marginal utility. Its lower price raises marginal utility per dollar, making it more attractive relative to other purchases. This concerns a budget-constrained choice, not the satiation point of total utility.')
for i,price in [(75,12),(76,7)]:
 fix('7-6',i,prompt=f'A perfectly competitive firm can produce only whole units. Its marginal variable costs for successive units are shown below; variable cost is zero at zero output. Fixed costs are unavoidable. At a market price of ${price}, what output maximises profit?\n| Output (units) | 1 | 2 | 3 | 4 | 5 |\n| Marginal cost ($) | 8 | 9 | 10 | 11 | 16 |',explanation=('Cumulative variable costs are $8, $17, $27, $38 and $54. At a price of $12, revenue minus variable cost is $4, $7, $9, $10 and $6. Producing four units maximises the contribution to fixed costs.' if i==75 else 'Cumulative variable costs are $8, $17, $27, $38 and $54, so the minimum average variable cost is $8. At a price of $7 every positive output has revenue below variable cost. Shutdown avoids that additional loss.'))
for i,old,new in [(93,'downward-sloping demand','straight-line downward-sloping demand over the relevant range'),(94,'upward-sloping supply','straight-line upward-sloping supply over the relevant range')]:fix('2-5',i,prompt=B['2-5'][i-1]['prompt'].replace(old,new))
fix('4-5',67,prompt=B['4-5'][66]['prompt'].replace('new unemployment rate?','new unemployment rate, rounded to the nearest whole percentage point?'))
fix('4-5',76,prompt=B['4-5'][75]['prompt'].replace('In which economy did the unemployment rate definitely fall because unemployed people found jobs rather than because they left the labour force?','Assume there are no movements into or out of economic inactivity. Which row is consistent with unemployed people finding jobs?'),explanation='With no flows into or out of inactivity, transitions between unemployment and employment leave the labour force unchanged. In D, employment rises by two and unemployment falls by two. Without the stated assumption, these net changes would not identify the gross flows.')
fix('7-3',77,prompt=B['7-3'][76]['prompt'].replace('Which description is best?','The extra X is allocated without reducing anyone’s consumption or welfare, and there are no other welfare losses. Which description is best?'),explanation='Moving to the frontier raises productive efficiency. The stated distribution and welfare assumptions also mean at least one person is better off and no one is worse off, so the move is a Pareto improvement.')
fix('7-6',98,prompt='Compare a profit-maximising, single-price monopolist with a competitive market facing the same downward-sloping demand and upward-sloping marginal cost. Assume interior solutions and no externalities. What is the monopoly outcome relative to competition?',choices=['A lower price and a higher output.','The same price and a lower output.','A higher price and a lower output.','A higher price and the same output.'],explanation='The monopolist chooses MR = MC, then charges the price on demand. Competition produces where P = MC. With the stated common demand and cost conditions, monopoly output is lower and its price is higher. This comparison does not establish which has higher average cost.')
fix('9-4',77,prompt='An outside cash deposit of $24 million enters a banking system with an 8% reserve ratio. Banks hold no excess reserves; borrowers redeposit all loans and there is no cash leakage. Under the simple deposit multiplier, what are the maximum increases in total deposits and new lending?',explanation='The deposit multiplier is 1/0.08 = 12.5. Total deposits rise by $24 million × 12.5 = $300 million, including the initial outside deposit. New lending is $300 million − $24 million = $276 million.')
fix('5-4',86,prompt='Labour productivity, measured as output per effective worker, rises by 6%, while the number of effective workers falls by 8%. Holding other capacity determinants fixed, what happens to total productive capacity?',choices=['It rises by 14%.','It falls by 2%.','It rises by 2.48%.','It falls by 2.48%.'],explanation='Capacity equals output per effective worker multiplied by the number of effective workers. The new capacity is 1.06 × 0.92 = 0.9752 of the original, a fall of 2.48%. The percentage changes compound rather than simply add.')
fix('6-2',84,choices=['Imports exactly exhaust the 100-unit quota.','Imports exceed the quota by 160 units.','Domestic output equals the 100-unit quota.','Domestic consumption equals the 100-unit quota.'],explanation='Imports equal domestic demand minus domestic supply: 260 − 160 = 100 units. They exhaust the quota. The data alone do not establish that the quota raises price above the free-trade price or creates positive quota rents.')
fix('8-3',92,explanation='Total earnings are $30 × 100 = $3000. Transfer earnings are the area under labour supply: ($10 × 100) + (½ × $20 × 100) = $2000. Economic rent is $3000 − $2000 = $1000.')
fix('10-1',76,prompt='After several years of deflation, inflation is now 0%, but output remains weak. A government treats this single indicator as proof of macroeconomic success. Which judgment is best?',choices=['The current inflation rate establishes that output has recovered.','The current inflation rate establishes that employment has recovered.','Price stability should be assessed alongside output and employment.','Past deflation establishes that current purchasing power is falling.'],explanation='A current inflation rate of zero means prices are unchanged over the measured period; it is not current deflation. After past deflation, weak output or employment can persist. One price indicator therefore does not establish success across all macroeconomic objectives.')
fix('7-3',87,prompt=B['7-3'][86]['prompt'].replace('Which additional condition','Assume consumers and firms are fully informed and there are no externalities. Which additional condition'))
fix('7-3',88,prompt='With full information and no externalities, a market produces where P = MC and firms operate at minimum average cost. What do these conditions establish?',choices=['Static efficiency and evidence of continuing product innovation.','Static efficiency without evidence of continuing product innovation.','Equal income distribution and evidence of continuing product innovation.','Equal income distribution without evidence of continuing product innovation.'],explanation='P = MC establishes allocative efficiency under the stated assumptions; minimum average cost establishes productive efficiency. These static conditions do not establish innovation over time or an equitable income distribution.')
fix('7-4',100,prompt='A government evaluates a flood-defence project. Some households gain protection, but nearby wetlands are lost. Why should the decision include both effects?',choices=['Public projects should be assessed using financial receipts alone.','Wetland losses should be counted only when compensation is paid.','Social appraisal includes benefits and costs beyond financial payments.','Household protection should be excluded from a public appraisal.'],explanation='Social cost-benefit analysis includes private and external effects, including non-market environmental losses and avoided flood damage. Identifying affected groups and valuing these effects helps assess the project’s net social benefit.')
fix('10-2',84,prompt='A country experiences higher inflation and lower growth after an adverse supply shock. What explains this combination?',choices=['A contraction of AD lowers both output and the price level.','An expansion of AD raises both output and the price level.','A contraction of SRAS lowers output and raises the price level.','An expansion of SRAS raises output and lowers the price level.'],explanation='An adverse supply shock shifts SRAS left. Holding AD unchanged, equilibrium real output falls and the price level rises, producing weaker growth alongside inflationary pressure.')
fix('7-8',91,prompt='A firm faces a straight-line downward-sloping demand curve and sells at its midpoint. What happens to total revenue after a small but non-zero price cut along this curve?',choices=['It rises because quantity sold increases.','It remains at its maximum despite the price cut.','It falls because the initial point maximises revenue.','It becomes zero because marginal revenue is zero.'],explanation='If P = a − bQ, total revenue is aQ − bQ² and is maximised at the demand midpoint Q = a/(2b). Any non-zero movement away reduces revenue. Unit elasticity describes the instantaneous percentage offset at the midpoint, not unchanged revenue after a finite price change.')
for q in B['4-1']:
 for f in ['prompt','explanation']:
  q[f]=q[f].replace('Indirect taxes','Taxes on products').replace('indirect taxes','taxes on products').replace('indirect tax','tax on products')
 for o in q['options']:o['text']=o['text'].replace('Indirect taxes','Taxes on products').replace('indirect taxes','taxes on products')
for s,b in B.items():(D/(s+'.json')).write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n')
(R/'audit/alevel/specific-corrections.json').write_text(json.dumps(ledger,ensure_ascii=False,indent=2)+'\n')
print(len(ledger),'specific corrections')
